export class SupplierConnectionsResource {
  constructor(private readonly transport: Transport) {}

  /**
   * [Both] The feed attempt log for one of your connections: every call to its automated-invoice route or its validate twin that reached the connection, newest first, 50 a page (`?before=` the last row's cursor for the next). Both sides see the same rows. 404 when the connection isn't yours
   */
  listFeedAttempts(connectionId: string, query?: QueryParams<"ListFeedAttempts">, options?: RequestOptions): Promise<ResponseBody<"ListFeedAttempts">> {
    return this.transport.request("get", "/supplier-connections/{connectionId}/feed-attempts", { path: { connectionId }, query, options }) as Promise<ResponseBody<"ListFeedAttempts">>;
  }

  /**
   * [Buyer] Turn this supplier's automated invoices on or off - whether it may send invoices to you with an invoices:feed API key (POST .../invoices/connections/:connectionId). On from the moment you approve the supplier; turning it off refuses the very next one, and invoices already received stay. Approved connections only (400 COUNTERPARTY_NOT_ACTIVE). Human session only.
   */
  setInvoiceFeed(connectionId: string, body: RequestBody<"SetInvoiceFeed">, options?: RequestOptions): Promise<ResponseBody<"SetInvoiceFeed">> {
    return this.transport.request("put", "/supplier-connections/{connectionId}/invoice-feed", { path: { connectionId }, body, options }) as Promise<ResponseBody<"SetInvoiceFeed">>;
  }

  /**
   * [Buyer] Set "Bills in" (billingCurrency, a supplier with no Pleaxy account only) and "Pay in" (paymentCurrency) for this supplier: the defaults for its new orders and invoices. Absent leaves a field, null removes it. Existing documents keep their currencies. 400 BILLING_CURRENCY_SUPPLIER_OWNED for a supplier with an account; 400 PAYMENT_CURRENCY_NOT_ACCEPTED when it doesn't accept that currency. The supplier never sees either.
   */
  setSupplierCurrencies(connectionId: string, body: RequestBody<"SetSupplierCurrencies">, options?: RequestOptions): Promise<ResponseBody<"SetSupplierCurrencies">> {
    return this.transport.request("put", "/supplier-connections/{connectionId}/currencies", { path: { connectionId }, body, options }) as Promise<ResponseBody<"SetSupplierCurrencies">>;
  }
}

export class WorkspacesResource {
  constructor(private readonly transport: Transport) {}

  /**
   * [Buyer] Get the buyer workspace snapshot - optionally scoped to a createdAt range via ?from=&to=. ?lists=none returns purchaseOrders and invoices empty, without reading them (page them with ListPurchaseOrdersPage and ListInvoicesPage), and the rest as usual. ?lists=active returns only the ones still in play - not canceled, closed, rejected or paid POs; unpaid invoices, and ones rejected in the last 30 days and not yet replaced - with recentPurchaseOrders and recentInvoices, the newest 10 of each.
   */
  getBuyerWorkspace(query?: QueryParams<"GetBuyerWorkspace">, options?: RequestOptions): Promise<ResponseBody<"GetBuyerWorkspace">> {
    return this.transport.request("get", "/buyer", { path: undefined, query, options }) as Promise<ResponseBody<"GetBuyerWorkspace">>;
  }

  /**
   * [Supplier] Get the supplier workspace snapshot - optionally scoped to a createdAt range via ?from=&to=. ?lists=none returns incomingPOs and supplierInvoices empty, without reading them (page them with ListPurchaseOrdersPage and ListInvoicesPage). ?lists=active returns only the ones still in play (as GetBuyerWorkspace), with recentIncomingPOs and recentSupplierInvoices, the newest 10 of each.
   */
  getSupplierWorkspace(query?: QueryParams<"GetSupplierWorkspace">, options?: RequestOptions): Promise<ResponseBody<"GetSupplierWorkspace">> {
    return this.transport.request("get", "/supplier", { path: undefined, query, options }) as Promise<ResponseBody<"GetSupplierWorkspace">>;
  }
}

/** Every resource, one per API area. */
export class Resources {
  readonly apiKeys: ApiKeysResource;
  readonly approvalSettings: ApprovalSettingsResource;
  readonly approvals: ApprovalsResource;
  readonly automationRules: AutomationRulesResource;
  readonly billing: BillingResource;
  readonly cloudConnections: CloudConnectionsResource;
  readonly documentSync: DocumentSyncResource;
  readonly employees: EmployeesResource;
  readonly exchangeRates: ExchangeRatesResource;
  readonly fulfillment: FulfillmentResource;
  readonly invoices: InvoicesResource;
  readonly notifications: NotificationsResource;
  readonly orgProfiles: OrgProfilesResource;
  readonly purchaseOrders: PurchaseOrdersResource;
  readonly settlement: SettlementResource;
  readonly supplierConnections: SupplierConnectionsResource;
  readonly workspaces: WorkspacesResource;

  constructor(transport: Transport) {
    this.apiKeys = new ApiKeysResource(transport);
    this.approvalSettings = new ApprovalSettingsResource(transport);
    this.approvals = new ApprovalsResource(transport);
    this.automationRules = new AutomationRulesResource(transport);
    this.billing = new BillingResource(transport);
    this.cloudConnections = new CloudConnectionsResource(transport);
    this.documentSync = new DocumentSyncResource(transport);
    this.employees = new EmployeesResource(transport);
    this.exchangeRates = new ExchangeRatesResource(transport);
    this.fulfillment = new FulfillmentResource(transport);
    this.invoices = new InvoicesResource(transport);
    this.notifications = new NotificationsResource(transport);
    this.orgProfiles = new OrgProfilesResource(transport);
    this.purchaseOrders = new PurchaseOrdersResource(transport);
    this.settlement = new SettlementResource(transport);
    this.supplierConnections = new SupplierConnectionsResource(transport);
    this.workspaces = new WorkspacesResource(transport);
  }
}
